import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test("uploading a document returns 201 as processing and is audited", { tag: "@DOC-01" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const vendorRes = await member.post("/api/vendors", {
    data: {
      name: uniqueName("Doc Vendor"),
      category: "services",
      contact_email: `doc-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@vendors-mail.com`,
    },
  });
  expect(vendorRes.status(), await vendorRes.text()).toBe(201);
  const vendor = await vendorRes.json();
  expect(vendor.status).toBe("draft");

  // Act
  const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "insurance_certificate",
      file: {
        name: "insurance_certificate.txt",
        mimeType: "text/plain",
        buffer: readFileSync(sample("insurance_certificate.txt")),
      },
    },
  });

  // Assert
  expect(res.status(), await res.text()).toBe(201);
  const document = await res.json();
  expect(document.status).toBe("processing");
  expect(document.kind).toBe("insurance_certificate");

  const auditRes = await member.get(`/api/vendors/${vendor.id}/audit`);
  expect(auditRes.status(), await auditRes.text()).toBe(200);
  const actions = ((await auditRes.json()).items as { action: string }[]).map((e) => e.action);
  expect(actions).toContain("document.uploaded");
});
